// Convert redacted text into HTML that preserves line breaks & paragraphs
const text = items[0].json.redactedText || '';

const escape = (s) => s
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// Split into paragraphs on blank lines, preserve single line breaks within a paragraph
const paragraphs = text
  .split(/\n\s*\n/)
  .map(p => escape(p.trim()).replace(/\n/g, '<br>'))
  .filter(p => p.length > 0);

const bodyHtml = paragraphs.map(p => `<p style="margin: 0 0 12px 0;">${p}</p>`).join('\n');

const html = `<html>
<head>
<style>
  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11pt;
    line-height: 1.5;
    padding: 40px;
    white-space: pre-wrap;
    word-wrap: break-word;
  }
  p { margin: 0 0 12px 0; }
</style>
</head>
<body>
${bodyHtml}
</body>
</html>`;

return [{
  json: {
    ...items[0].json,
    html
  }
}];

