// Parse the AI's JSON output and redact each PII value from the original text.
const aiOutput = items[0].json.message?.content || items[0].json.text || items[0].json.output;
let parsed;
try {
  parsed = typeof aiOutput === 'string' ? JSON.parse(aiOutput) : aiOutput;
} catch (e) {
  parsed = { redactions: [] };
}

const originalText = $('Extract Text From PDF1').item.json.text;
let redactedText = originalText;
const log = [];

for (const item of (parsed.redactions || [])) {
  if (!item.value) continue;
  const escaped = item.value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(escaped, 'g');
  const before = redactedText;
  redactedText = redactedText.replace(regex, `[REDACTED:${item.type || 'PII'}]`);
  if (before !== redactedText) {
    log.push({ value: item.value, type: item.type });
  }
}

return [{
  json: {
    redactedText,
    originalText,
    redactionCount: log.length,
    redactionLog: log
  }
}];
